-- Reject household fragrances and ingredients from existing food targets.
UPDATE monitoring_targets SET criteria=jsonb_set(criteria, '{excluded_terms}',
    (criteria->'excluded_terms') || '["detergente","sabonete","limpador","desinfetante","sabao","amaciante","alvejante","creme dental"]'::jsonb)
WHERE id IN ('maca', 'laranja', 'manteiga', 'oleo-soja');

